-- Transactional integration suite. All fixtures and mutations roll back.
begin;
create temporary table test_results(name text,passed boolean);
create function pg_temp.ok(p boolean,n text) returns void language plpgsql as $$begin if p is distinct from true then raise exception 'FAILED: %',n;end if;insert into test_results values(n,true);end$$;
create function pg_temp.fails(q text,expected text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if position(expected in sqlerrm)>0 then insert into test_results values(n,true);return;else raise;end if;end;raise exception 'FAILED: % did not reject',n;end$$;
create temporary table fixture(key text primary key,value jsonb);
insert into auth.users(id,aud,role,email) values('11111111-1111-4111-8111-111111111111','authenticated','authenticated','test-founder@example.invalid'),('22222222-2222-4222-8222-222222222222','authenticated','authenticated','test-cashier@example.invalid');
insert into auth.sessions(id,user_id,created_at,updated_at) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111',now(),now()),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','22222222-2222-4222-8222-222222222222',now(),now());
insert into public.staff_roles(user_id,role,must_change_password) values('11111111-1111-4111-8111-111111111111','founder',false),('22222222-2222-4222-8222-222222222222','cashier',false);
insert into public.branches(id,name,instapay_details) values('33333333-3333-4333-8333-333333333333','TEST ONLY','TEST ONLY - DO NOT TRANSFER');
insert into public.categories values('__test','TEST ONLY');
insert into public.products(id,slug,name,category_id,price_minor) values('__test','test-only','Test Latte','__test',12500),('__test_other','test-other','Other','__test',5000);
insert into public.variants(id,product_id,name,price_minor) values('44444444-4444-4444-8444-444444444444','__test_other','Large',8000);
insert into public.modifiers(id,name,price_minor) values('55555555-5555-4555-8555-555555555555','Extra shot',2000);
insert into public.product_modifiers values('__test','55555555-5555-4555-8555-555555555555');
insert into fixture values('payload','{"branch_id":"33333333-3333-4333-8333-333333333333","source":"web","fulfillment":"takeaway","customer_name":"TEST","payment_method":"cash","items":[{"product_id":"__test","quantity":2,"modifier_ids":["55555555-5555-4555-8555-555555555555"]}]}'::jsonb);
insert into fixture values('quote',public.bareeq_quote((select value from fixture where key='payload')));
select pg_temp.ok((select (value->>'total_minor')::integer=29000 from fixture where key='quote'),'authoritative pricing includes quantity and extra');
update fixture set value=value||jsonb_build_object('quote_hash',(select value->>'quote_hash' from fixture where key='quote')) where key='payload';
insert into fixture values('cash',public.bareeq_create((select value from fixture where key='payload'),'66666666-6666-4666-8666-666666666666',repeat('a',64)));
select pg_temp.ok((select value->>'status'='new' from fixture where key='cash'),'cash reaches actionable queue');
select pg_temp.ok(public.bareeq_create((select value from fixture where key='payload'),'66666666-6666-4666-8666-666666666666',repeat('a',64))->>'id'=(select value->>'id' from fixture where key='cash'),'retry returns same order');
select pg_temp.fails($q$select public.bareeq_create((select value from fixture where key='payload'),'66666666-6666-4666-8666-666666666666',repeat('b',64))$q$,'IDEMPOTENCY_CONFLICT','idempotency token collision rejected');
select pg_temp.fails($q$select public.bareeq_create((select value||'{"source":"cashier"}'::jsonb from fixture where key='payload'),gen_random_uuid(),repeat('b',64))$q$,'FORBIDDEN','anonymous cannot create counter order');
select pg_temp.fails($q$select public.bareeq_quote((select jsonb_set(value,'{items,0,quantity}','0') from fixture where key='payload'))$q$,'INVALID_QUANTITY','zero quantity rejected');
select pg_temp.fails($q$select public.bareeq_quote((select jsonb_set(value,'{items,0,quantity}','-1') from fixture where key='payload'))$q$,'INVALID_QUANTITY','negative quantity rejected');
select pg_temp.fails($q$select public.bareeq_quote((select jsonb_set(value,'{items,0,quantity}','100') from fixture where key='payload'))$q$,'INVALID_QUANTITY','excessive quantity rejected');
select pg_temp.fails($q$select public.bareeq_quote((select jsonb_set(value,'{items,0,variant_id}','"44444444-4444-4444-8444-444444444444"') from fixture where key='payload'))$q$,'INVALID_VARIANT','wrong product variant rejected');
select pg_temp.fails($q$select public.bareeq_quote((select jsonb_set(value,'{items,0,modifier_ids}','["44444444-4444-4444-8444-444444444444"]') from fixture where key='payload'))$q$,'INVALID_MODIFIER','forged modifier rejected');
update public.products set available=false where id='__test';
select pg_temp.fails($q$select public.bareeq_create((select value from fixture where key='payload'),gen_random_uuid(),repeat('a',64))$q$,'PRODUCT_UNAVAILABLE','sold-out race revalidated');
update public.products set available=true,price_minor=13000 where id='__test';
select pg_temp.ok(public.bareeq_create((select value from fixture where key='payload'),gen_random_uuid(),repeat('a',64))->>'price_changed'='true','price race returns updated quote without creating');
select pg_temp.ok((select count(*)=1 from public.orders where branch_id='33333333-3333-4333-8333-333333333333'),'failed submissions leave no partial orders');
update public.products set price_minor=12500 where id='__test';
insert into fixture values('insta',public.bareeq_create((select value||'{"payment_method":"instapay"}'::jsonb from fixture where key='payload'),'77777777-7777-4777-8777-777777777777',repeat('c',64)));
select pg_temp.ok((select value->>'status'='awaiting_receipt' from fixture where key='insta'),'instapay waits for receipt');
select pg_temp.fails($q$select public.bareeq_receipt((select (value->>'id')::uuid from fixture where key='insta'),repeat('d',64),'test.jpg')$q$,'FORBIDDEN','wrong receipt capability rejected');
select public.bareeq_receipt((select (value->>'id')::uuid from fixture where key='insta'),repeat('c',64),'test.jpg');
select pg_temp.ok((select status='awaiting_payment_verification' from public.orders where id=(select (value->>'id')::uuid from fixture where key='insta')),'receipt does not verify transfer');
select pg_temp.fails($q$select public.bareeq_transition((select (value->>'id')::uuid from fixture where key='insta'),'new','22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')$q$,'FORBIDDEN','cashier cannot verify');
select pg_temp.fails($q$select public.bareeq_transition((select (value->>'id')::uuid from fixture where key='insta'),'accepted','22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')$q$,'PAYMENT_NOT_VERIFIED','unverified transfer cannot enter preparation');
-- Validate actual RLS with cashier JWT claims before verification.
grant select on fixture to authenticated;
grant select,insert on test_results to authenticated, anon;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated","session_id":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb","user_metadata":{"role":"founder"}}',true);
select pg_temp.ok(not exists(select 1 from public.orders where id=(select (value->>'id')::uuid from fixture where key='insta')),'RLS hides pending InstaPay even with forged metadata');
select pg_temp.ok(exists(select 1 from public.orders where id=(select (value->>'id')::uuid from fixture where key='cash')),'RLS cashier sees actionable cash');
select pg_temp.fails('select * from public.receipts','permission denied','cashier cannot read receipt paths');
select pg_temp.fails('update public.staff_roles set role=''founder''','permission denied','cashier cannot edit roles');
select pg_temp.fails('select public.bareeq_quote(''{}''::jsonb)','permission denied','privileged RPC cannot be called directly');
reset role;
select public.bareeq_transition((select (value->>'id')::uuid from fixture where key='insta'),'new','11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
select public.bareeq_transition((select (value->>'id')::uuid from fixture where key='insta'),'new','11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
select pg_temp.ok((select count(*)=1 from public.order_events where order_id=(select (value->>'id')::uuid from fixture where key='insta') and new_state='new'),'repeat verification creates one transition');
select pg_temp.ok((select status='verified' and verified_by='11111111-1111-4111-8111-111111111111' and verified_at is not null from public.payments where order_id=(select (value->>'id')::uuid from fixture where key='insta')),'payment verification is audited');
select pg_temp.fails($q$select public.bareeq_transition((select (value->>'id')::uuid from fixture where key='cash'),'completed','22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')$q$,'INVALID_TRANSITION','cannot skip preparation lifecycle');
select public.bareeq_transition((select (value->>'id')::uuid from fixture where key='cash'),'accepted','22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
select public.bareeq_transition((select (value->>'id')::uuid from fixture where key='cash'),'preparing','22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
select public.bareeq_transition((select (value->>'id')::uuid from fixture where key='cash'),'ready','22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
select public.bareeq_transition((select (value->>'id')::uuid from fixture where key='cash'),'completed','22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
insert into fixture values('reject',public.bareeq_create((select value||'{"payment_method":"instapay"}'::jsonb from fixture where key='payload'),gen_random_uuid(),repeat('e',64)));
select public.bareeq_receipt((select (value->>'id')::uuid from fixture where key='reject'),repeat('e',64),'reject.jpg');
select public.bareeq_transition((select (value->>'id')::uuid from fixture where key='reject'),'payment_rejected','11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','No incoming transfer');
select pg_temp.ok(not exists(select 1 from public.notification_outbox where order_id=(select (value->>'id')::uuid from fixture where key='reject') and audience='cashier'),'rejected payment never notifies cashier');
select pg_temp.fails($q$select public.bareeq_transition((select (value->>'id')::uuid from fixture where key='reject'),'new','11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')$q$,'INVALID_TRANSITION','rejected payment cannot later be confirmed');
select pg_temp.ok(public.bareeq_create((select value||'{"source":"cashier","fulfillment":"dine_in"}'::jsonb from fixture where key='payload'),gen_random_uuid(),repeat('f',64),'22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')->>'total_minor'='29000','cashier dine-in uses DB pricing');
select pg_temp.ok(public.bareeq_create((select value||'{"source":"cashier","fulfillment":"takeaway"}'::jsonb from fixture where key='payload'),gen_random_uuid(),repeat('f',64),'22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')->>'total_minor'='29000','cashier takeaway uses DB pricing');
set local role authenticated;
select pg_temp.ok(not exists(select 1 from public.orders where id=(select (value->>'id')::uuid from fixture where key='reject')),'RLS hides rejected payment');
select pg_temp.ok(exists(select 1 from public.orders where id=(select (value->>'id')::uuid from fixture where key='insta')),'verified InstaPay becomes visible to cashier');
reset role;
update public.products set price_minor=1 where id='__test';
select pg_temp.ok((public.bareeq_report((now() at time zone 'Africa/Cairo')::date,'33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'revenue_minor')::integer=29000,'report uses immutable snapshots not new menu price');
select pg_temp.fails($q$select public.bareeq_report(current_date,'33333333-3333-4333-8333-333333333333','22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')$q$,'FORBIDDEN','cashier cannot run founder reports');
update public.receipts set deleted_at=now() where path='test.jpg';
select pg_temp.ok(exists(select 1 from public.payments where order_id=(select (value->>'id')::uuid from fixture where key='insta')),'receipt removal preserves payment history');
delete from auth.sessions where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
select pg_temp.ok(public.bareeq_staff('22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb') is null,'revoked session denied');
set local role authenticated;
select pg_temp.ok(not exists(select 1 from public.orders),'revoked session cannot read any orders');
reset role;
set local role anon;
select pg_temp.fails('select * from public.orders','permission denied','anonymous cannot read orders');
select pg_temp.fails('select * from public.receipts','permission denied','anonymous cannot read receipts');
reset role;
select jsonb_agg(test_results) as test_results from test_results;
rollback;

